let state={page:'overview',search:'',type:'全部类型',location:'全部位置',product:'全部产品',selected:'DC-A100-02',factory:'苏州封装厂',productPage:'A100'};
const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
async function api(path,options={}){const response=await fetch(path,{credentials:'same-origin',headers:options.body instanceof FormData?{}:{'Content-Type':'application/json'},...options});const data=await response.json();if(!response.ok){if(response.status===401)showLogin();throw new Error(data.error||'操作失败')}return data}
async function loadData(){try{[assets,shipments,uploadedFiles,releases]=await Promise.all([api('/api/assets'),api('/api/shipments'),api('/api/files'),api('/api/releases')]);if(state.selected&&!assets.some(a=>a.id===state.selected))state.selected=assets[0]?.id||null;render()}catch(error){toast(`数据库连接失败：${error.message}`)}}
function toast(msg){const el=$('#toast');el.textContent='✓  '+msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2100)}
function renderNav(){ $('#nav').innerHTML=navItems.map(([k,i,l])=>`<button data-page="${k}" class="${state.page===k?'active':''}"><i>${i}</i>${l}</button>`).join(''); }
function setTitle(t){$('#pageTitle').textContent=t;$('#breadcrumb').textContent=`测试资源管理 / ${t}`}
function typeCount(t,list=assets){return list.filter(a=>a.type===t).reduce((s,a)=>s+a.qty,0)}
function selectOptions(arr,current){return arr.map(v=>`<option ${v===current?'selected':''}>${v}</option>`).join('')}
function render(){renderNav();const title=navItems.find(n=>n[0]===state.page)[2];setTitle(title);({overview, factoriesView, productsView, shipmentsView, filesView, releasesView}[state.page==='factories'?'factoriesView':state.page==='products'?'productsView':state.page==='shipments'?'shipmentsView':state.page==='files'?'filesView':state.page==='releases'?'releasesView':'overview'])();applyRole();bind();}
function summary(){return `<section class="cards">${['LB','Socket','测试机','DC线'].map(t=>`<article class="summary"><div class="icon ${t}">${icons[t]}</div><div><span>${t}</span><strong>${typeCount(t)}<small>${t==='测试机'?'台':t==='DC线'?'套':'件'}</small></strong><p>我司现有 ${typeCount(t,assets.filter(a=>a.location==='我司仓库'))}</p></div></article>`).join('')}</section>`}
function assetRows(list){return list.map(a=>`<tr data-id="${a.id}" class="${state.selected===a.id?'selected':''}"><td><b>产品 ${a.product}</b></td><td>${a.type}</td><td><b>${a.id}</b><small>${a.model}</small></td><td><span class="pill location ${a.location==='我司仓库'?'home':''}">● ${a.location}</span></td><td>${a.qty}${a.unit}</td><td>${a.date}</td><td><span class="status ${a.status}">${a.status}</span></td><td><button class="file" data-file="${a.file}">⌕ ${a.file}</button></td><td>›</td></tr>`).join('')}
function detail(a){if(!a)return'';return `<aside class="detail"><div class="detail-top"><div class="icon ${a.type}">${icons[a.type]}</div><button data-close-detail>×</button></div><h2>${a.id}</h2><p>${a.model}</p><div class="info"><label>适配产品<b>${a.product}</b></label><label>当前数量<b>${a.qty}${a.unit}</b></label><label>当前位置<b>${a.location}</b></label><label>寄出日期<b>${a.date}</b></label><label>适配设备<b>${a.fit||'—'}</b></label><label>当前状态<b><span class="status ${a.status}">${a.status}</span></b></label></div><div class="attachment"><small>关联附件</small><b>▤ ${a.file}</b></div><div class="attachment"><small>备注</small><b style="color:#273447">${a.note}</b></div><div class="detail-actions"><button class="primary" data-edit="${a.id}">编辑资料</button><button class="outline" data-ship="${a.id}">登记寄送</button><button class="outline" data-upload="${a.id}">上传附件</button><button class="danger" data-delete="${a.id}">删除资产</button></div></aside>`}
function overview(){const q=state.search.toLowerCase();const list=assets.filter(a=>(!q||[a.id,a.product,a.type,a.model,a.location].some(v=>v.toLowerCase().includes(q)))&&(state.type==='全部类型'||a.type===state.type)&&(state.location==='全部位置'||a.location===state.location)&&(state.product==='全部产品'||a.product===state.product));const a=assets.find(x=>x.id===state.selected);$('#view').innerHTML=`<div class="content">${summary()}<section class="panel inventory"><div><div class="panel-head"><div><h2>全部资产</h2><p>共 ${list.length} 条记录，点击一行查看详细信息</p></div><button class="outline" data-demo="导出Excel">▦ 导出 Excel</button></div><div class="filters"><select id="fProduct">${selectOptions(['全部产品',...new Set(assets.map(a=>a.product))],state.product)}</select><select id="fType">${selectOptions(['全部类型','LB','Socket','测试机','DC线'],state.type)}</select><select id="fLocation">${selectOptions(['全部位置','我司仓库',...factories],state.location)}</select></div><div class="table-wrap"><table><thead><tr><th>产品</th><th>资产类型</th><th>资产编号 / 型号</th><th>当前所在位置</th><th>数量</th><th>寄出日期</th><th>状态</th><th>图纸 / 文件</th><th></th></tr></thead><tbody>${assetRows(list)}</tbody></table></div></div>${detail(a)}</section></div>`}
function factoriesView(){const list=assets.filter(a=>a.location===state.factory);$('#view').innerHTML=`<div class="content"><section class="factory-grid">${factories.map(f=>{const x=assets.filter(a=>a.location===f);return `<button class="factory-card ${f===state.factory?'active':''}" data-factory="${f}"><i>▥</i><h3>${f}</h3><p><strong>${x.reduce((s,a)=>s+a.qty,0)}</strong> 件资产 · ${x.length} 个编号</p><div class="mini-types">${['LB','Socket','测试机','DC线'].map(t=>`<span>${t} ${typeCount(t,x)}</span>`).join('')}</div></button>`}).join('')}</section><section class="panel"><div class="panel-head"><div><h2>${state.factory} · 现有物料</h2><p>查看该厂全部测试资源与寄送日期</p></div><button class="outline" data-demo="导出工厂清单">导出清单</button></div>${assetGrid(list)}</section></div>`}
function assetGrid(list){return `<div class="asset-grid">${list.length?list.map(a=>`<button class="asset-card" data-id="${a.id}"><div class="icon ${a.type}">${icons[a.type]}</div><div><small>${a.type}</small><h3>${a.id}</h3><p>${a.model}</p></div><footer><span>${a.date}</span><b>${a.qty}${a.unit}</b></footer></button>`).join(''):'<div class="empty">暂无登记资产</div>'}</div>`}
function productsView(){const ps=[...new Set(assets.map(a=>a.product))],list=assets.filter(a=>a.product===state.productPage);$('#view').innerHTML=`<div class="content product-layout"><aside class="panel product-list"><h2>产品列表</h2><p>选择产品查看完整配套</p>${ps.map(p=>`<button data-product-page="${p}" class="${p===state.productPage?'active':''}"><div><strong>产品 ${p}</strong><small>${assets.filter(a=>a.product===p).length}项配套资产</small></div><b>›</b></button>`).join('')}</aside><section class="panel"><div class="product-hero"><div><small>PRODUCT KIT</small><h2>产品 ${state.productPage} 测试配套</h2><p>LB、Socket、测试机和DC线的完整关联关系</p></div><strong style="font-size:30px">${list.length}<small style="font-size:9px;display:block">项配套</small></strong></div><div class="relation">${['测试机','DC线','LB','Socket'].map(t=>{const a=list.find(x=>x.type===t);return `<div><i class="icon ${t}">${icons[t]}</i><span>${t}</span><b>${a?.id||'暂未配置'}</b></div>`}).join('')}</div>${assetGrid(list)}</section></div>`}
function shipmentsView(){const list=shipments;const latest=list[0];const factoryCount=new Set(list.map(a=>a.to_location)).size;$('#view').innerHTML=`<div class="content"><section class="stats"><article><span>寄送记录</span><strong>${list.length}</strong><small>数据库已永久保存</small></article><article><span>涉及封装厂</span><strong>${factoryCount}</strong><small>共5家合作封装厂</small></article><article><span>最近寄送</span><strong>${latest?latest.sent_date.slice(5):'—'}</strong><small>${latest?`寄往${latest.to_location}`:'暂无记录'}</small></article></section><section class="panel"><div class="panel-head"><div><h2>寄送记录</h2><p>保留每次寄送的时间、去向和关联资料</p></div><button class="primary" data-open="ship">＋ 新增寄送</button></div><div class="timeline">${list.map(a=>`<button data-id="${a.asset_id}"><time><b>${a.sent_date.slice(5)}</b><small>${a.sent_date.slice(0,4)}</small></time><div><h3>${a.type} · ${a.asset_id}</h3><p>产品 ${a.product} · ${a.model}${a.tracking_no?` · ${a.tracking_no}`:''}</p></div><div class="route">${a.from_location}　→　<b>${a.to_location}</b></div><b class="qty">${a.qty}${a.unit}</b><span class="status ${a.status}">${a.status}</span><b>›</b></button>`).join('')||'<div class="empty">暂无寄送记录</div>'}</div></section></div>`}
function filesView(){const group=[['LB','LB图纸'],['Socket','Socket图纸'],['测试机','测试机资料'],['DC线','DC线接线图']];$('#view').innerHTML=`<div class="content"><section class="folders">${group.map(([t,n])=>`<article class="folder"><i>▰</i><div><span>${n}</span><b>${uploadedFiles.filter(a=>a.type===t).length} 个已上传文件</b></div></article>`).join('')}</section><section class="panel"><div class="panel-head"><div><h2>已上传资料</h2><p>文件实际保存在本地 uploads 目录，记录保存在SQLite</p></div><button class="primary" data-upload="${state.selected||assets[0]?.id||''}">＋ 上传文件</button></div><div class="file-row head"><span>文件名称</span><span>关联资产</span><span>产品</span><span>类型</span><span>上传时间</span><span></span></div>${uploadedFiles.map(f=>`<div class="file-row"><div class="file-name"><b>${f.original_name}</b><small>${Math.max(1,Math.round(f.size/1024))} KB</small></div><span>${f.asset_id}</span><span>产品 ${f.product}</span><span>${f.type}</span><span>${f.created_at.slice(0,10)}</span><button data-download="${f.id}">⇩ 下载</button></div>`).join('')||'<div class="empty">还没有真实上传的文件，点击“上传文件”测试</div>'}</section></div>`}
function openModal(kind,id){if(id)state.selected=id;const a=assets.find(x=>x.id===state.selected);let html='';if(kind==='add')html=`<div class="modal-title"><i>＋</i><div><h2>新增资产</h2><p>登记新的测试资源，保存到本地数据库</p></div></div><form id="addForm"><div class="form"><label>产品型号<input name="product" placeholder="例如 A100" required></label><label>资产类型<select name="type"><option>LB</option><option>Socket</option><option>测试机</option><option>DC线</option></select></label><label>资产编号<input name="id" placeholder="例如 LB-A100-02" required></label><label>型号 / 规格<input name="model" placeholder="例如 QFN-64 Load Board" required></label><label>数量<input name="qty" type="number" value="1" min="1" required></label><label>初始位置<input value="我司仓库" disabled></label><label class="full">适配设备<input name="fit" placeholder="例如 TESTER-03 / J750"></label><label class="full">备注<textarea name="note" placeholder="资产用途或其他说明"></textarea></label></div><div class="modal-actions"><button type="button" class="outline close-modal">取消</button><button class="primary">保存资产</button></div></form>`;else if(kind==='ship')html=`<div class="modal-title"><i>↗</i><div><h2>登记寄送</h2><p>记录将永久保存在寄送历史中</p></div></div>${a?`<div class="selected-asset"><small>${a.type} · 产品 ${a.product}</small><b>${a.id}　${a.model}</b></div>`:'<div class="empty">请先选择一项资产</div>'}<form id="shipForm"><div class="form"><label>目的封装厂<select name="location">${factories.map(f=>`<option>${f}</option>`).join('')}</select></label><label>寄出日期<input name="date" type="date" value="2026-08-14" required></label><label>快递单号<input name="tracking_no" placeholder="例如 SF123456789"></label><label>经手人<input name="handler" placeholder="例如 陈工"></label><label class="full">备注<textarea name="note" placeholder="联系人或其他说明"></textarea></label></div><div class="modal-actions"><button type="button" class="outline close-modal">取消</button><button class="primary" ${a?'':'disabled'}>确认寄送</button></div></form>`;else if(kind==='edit'&&a)html=`<div class="modal-title"><i>✎</i><div><h2>编辑资产</h2><p>${a.id} 的修改将写入本地数据库</p></div></div><form id="editForm"><div class="form"><label>产品型号<input name="product" value="${esc(a.product)}" required></label><label>资产类型<select name="type">${selectOptions(['LB','Socket','测试机','DC线'],a.type)}</select></label><label>型号 / 规格<input name="model" value="${esc(a.model)}" required></label><label>数量<input name="qty" type="number" value="${a.qty}" min="1" required></label><label>当前位置<select name="location">${selectOptions(['我司仓库',...factories],a.location)}</select></label><label>状态<select name="status">${selectOptions(['可用','使用中','维护中'],a.status)}</select></label><label class="full">适配设备<input name="fit" value="${esc(a.fit||'')}"></label><label class="full">备注<textarea name="note">${esc(a.note||'')}</textarea></label></div><div class="modal-actions"><button type="button" class="outline close-modal">取消</button><button class="primary">保存修改</button></div></form>`;else if(kind==='upload')html=`<div class="modal-title"><i>⇧</i><div><h2>上传附件</h2><p>文件保存在本地 uploads 目录</p></div></div><form id="uploadForm"><div class="form"><label class="full">关联资产<select name="asset_id">${assets.map(x=>`<option ${a&&x.id===a.id?'selected':''} value="${x.id}">${x.id} · ${x.type} · 产品${x.product}</option>`).join('')}</select></label><label class="full">选择文件<input name="file" type="file" required></label></div><div class="modal-actions"><button type="button" class="outline close-modal">取消</button><button class="primary">上传并保存</button></div></form>`;$('#modalRoot').innerHTML=`<div class="modal-bg"><div class="modal"><button class="close">×</button>${html}</div></div>`;bindModal()}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;state.selected=null;render()});document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openModal(b.dataset.open));document.querySelectorAll('[data-id]').forEach(b=>b.onclick=e=>{if(e.target.closest('[data-file]'))return;state.selected=b.dataset.id;if(state.page==='overview')render();else{state.page='overview';render()}});document.querySelectorAll('[data-file]').forEach(b=>b.onclick=e=>{e.stopPropagation();toast('这是示例文件名；可在图纸资料页上传真实文件')});document.querySelectorAll('[data-download]').forEach(b=>b.onclick=()=>location.href=`/api/files/${b.dataset.download}`);document.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>toast(`${b.dataset.demo}功能已打开（原型演示）`));document.querySelectorAll('[data-ship]').forEach(b=>b.onclick=()=>openModal('ship',b.dataset.ship));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openModal('edit',b.dataset.edit));document.querySelectorAll('[data-upload]').forEach(b=>b.onclick=()=>openModal('upload',b.dataset.upload));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{if(!confirm(`确认删除资产 ${b.dataset.delete}？寄送历史和附件也会一并删除。`))return;try{await api(`/api/assets/${encodeURIComponent(b.dataset.delete)}`,{method:'DELETE'});state.selected=null;await loadData();toast('资产已删除')}catch(e){toast(e.message)}});document.querySelectorAll('[data-factory]').forEach(b=>b.onclick=()=>{state.factory=b.dataset.factory;render()});document.querySelectorAll('[data-product-page]').forEach(b=>b.onclick=()=>{state.productPage=b.dataset.productPage;render()});const close=document.querySelector('[data-close-detail]');if(close)close.onclick=()=>{state.selected=null;render()};const fp=$('#fProduct'),ft=$('#fType'),fl=$('#fLocation');if(fp)fp.onchange=()=>{state.product=fp.value;render()};if(ft)ft.onchange=()=>{state.type=ft.value;render()};if(fl)fl.onchange=()=>{state.location=fl.value;render()}}
function bindModal(){document.querySelector('.modal-bg').onclick=e=>{if(e.target.classList.contains('modal-bg'))closeModal()};document.querySelector('.modal .close').onclick=closeModal;document.querySelectorAll('.close-modal').forEach(b=>b.onclick=closeModal);const add=$('#addForm');if(add)add.onsubmit=async e=>{e.preventDefault();try{const a=await api('/api/assets',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(add)))});state.selected=a.id;closeModal();state.page='overview';await loadData();toast(`已新增 ${a.id}`)}catch(err){toast(err.message)}};const ship=$('#shipForm');if(ship)ship.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(ship));d.asset_id=state.selected;try{await api('/api/shipments',{method:'POST',body:JSON.stringify(d)});closeModal();state.page='overview';await loadData();toast(`已登记寄送至${d.location}`)}catch(err){toast(err.message)}};const edit=$('#editForm');if(edit)edit.onsubmit=async e=>{e.preventDefault();try{await api(`/api/assets/${encodeURIComponent(state.selected)}`,{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(edit)))});closeModal();await loadData();toast('资产资料已保存')}catch(err){toast(err.message)}};const upload=$('#uploadForm');if(upload)upload.onsubmit=async e=>{e.preventDefault();try{await api('/api/files',{method:'POST',body:new FormData(upload)});closeModal();state.page='files';await loadData();toast('附件上传成功')}catch(err){toast(err.message)}}}
function releasesView(){const latest=releases[0];$('#view').innerHTML=`<div class="content release-layout"><section class="release-hero"><div><span>CHANGELOG</span><h2>版本更新记录</h2><p>每次软件更新后，在这里记录本次新增、优化和修复内容。</p></div><div class="current-version"><small>当前版本</small><strong>${latest?.version||'v0.1.0'}</strong><span>${latest?.released_at||''}</span></div></section><section class="release-body"><div class="release-list">${releases.map((r,index)=>`<article class="release-item"><div class="release-marker"><i>${index===0?'NEW':'✓'}</i><span></span></div><div class="release-card"><header><div><span>${r.version}</span><h3>${r.title}</h3></div><time>${r.released_at}</time></header><p>${esc(r.content).replace(/\n/g,'<br>')}</p></div></article>`).join('')||'<div class="empty">暂无版本记录</div>'}</div><aside class="publish-release admin-only"><span>管理员功能</span><h3>发布更新说明</h3><p>完成一次更新后，填写版本号和更新内容。</p><form id="releaseForm"><label>版本号<input name="version" placeholder="例如 v0.3.0" required></label><label>更新标题<input name="title" placeholder="简要描述本次更新" required></label><label>发布日期<input name="released_at" type="date" value="2026-08-14" required></label><label>更新说明<textarea name="content" placeholder="逐条填写新增、优化或修复内容" required></textarea></label><button class="primary">发布版本说明</button></form></aside></section></div>`;bindReleaseForm()}
function bindReleaseForm(){const form=$('#releaseForm');if(form)form.onsubmit=async e=>{e.preventDefault();try{await api('/api/releases',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});await loadData();toast('版本说明已发布')}catch(err){toast(err.message)}}}
function closeModal(){$('#modalRoot').innerHTML=''}
$('#search').addEventListener('input',e=>{state.search=e.target.value;if(state.page!=='overview')state.page='overview';render()});
function applyRole(){const guest=currentUser?.role==='guest';document.body.classList.toggle('guest-mode',guest);document.querySelectorAll('.admin-only,[data-open="add"],[data-open="ship"],[data-edit],[data-ship],[data-upload],[data-delete]').forEach(el=>el.style.display=guest?'none':'');$('#profileAvatar').textContent=guest?'访':'管';$('#profileName').textContent=guest?'临时访问':'管理员';$('#profileRole').textContent=guest?'只读权限 · 点击退出':'完整权限 · 点击退出'}
function showLogin(){$('#loginScreen').classList.add('show');document.querySelector('.app').classList.add('locked')}
function hideLogin(){$('#loginScreen').classList.remove('show');document.querySelector('.app').classList.remove('locked')}
async function initAuth(){try{const me=await api('/api/me');if(!me.authenticated){showLogin();return}currentUser=me;hideLogin();await loadData()}catch(e){showLogin()}}
$('#adminLoginChoice').onclick=()=>{$('.account-options').classList.add('hidden');$('#loginForm').classList.remove('hidden');$('#loginForm input[name="password"]').focus()};
$('#backToAccounts').onclick=()=>{$('#loginForm').classList.add('hidden');$('.account-options').classList.remove('hidden')};
$('#guestLogin').onclick=async()=>{try{await api('/api/login',{method:'POST',body:JSON.stringify({mode:'guest'})});currentUser=await api('/api/me');hideLogin();await loadData()}catch(e){toast(e.message)}};
$('#loginForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));try{await api('/api/login',{method:'POST',body:JSON.stringify({mode:'admin',...d})});currentUser=await api('/api/me');hideLogin();await loadData()}catch(err){toast(err.message)}};
$('#logoutButton').onclick=async()=>{await api('/api/logout',{method:'POST',body:'{}'});currentUser=null;showLogin()};
initAuth();
